const imageExtensions = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "image/avif": "avif",
  "image/jxl": "jxl",
  "image/heic": "heic",
};
function planImage(item, folderId) {
  if (!Object.hasOwn(imageExtensions, item?.mimeType)) return null;
  if (
    typeof folderId !== "string" ||
    folderId === "YOUR_OUTPUT_FOLDER_ID" ||
    !/^[A-Za-z0-9_-]{2,512}$/.test(folderId)
  ) {
    throw new Error("Configure a Google Drive output folder");
  }
  if (!Array.isArray(item.parents) || !item.parents.length || item.parents.includes(folderId)) {
    throw new Error("Use a separate destination folder for optimised copies");
  }
  const id = item.fileId ?? item.id;
  if (typeof id !== "string" || !/^[A-Za-z0-9_-]+$/.test(id) || !item.name?.trim()) {
    throw new Error("Drive event did not identify the image");
  }
  const outputMime = item.mimeType === "image/heic" ? "image/jpeg" : item.mimeType;
  const base = item.name.replace(/\.(?:jpe?g|png|webp|avif|jxl|heic)$/i, "");
  const extension =
    outputMime === "image/jpeg" && /\.jpeg$/i.test(item.name)
      ? "jpeg"
      : imageExtensions[outputMime];
  return {
    id,
    inputMime: item.mimeType,
    outputMime,
    name: base + "-optimised." + extension,
    folderId,
  };
}
const folderId = "YOUR_OUTPUT_FOLDER_ID";
return $input.all().flatMap(({ json }, index) => {
  const image = planImage(json, folderId);
  return image ? [{ json: image, pairedItem: { item: index } }] : [];
});

function checkShrink({ url, id, info, outputMime }) {
  const match =
    typeof url === "string" && /^https:\/\/api\.tinify\.com\/output\/([A-Za-z0-9_-]+)$/.exec(url);
  if (!match || (id !== undefined && id !== match[1])) {
    throw new Error("Tinify returned an invalid output URL");
  }
  if (info?.type !== outputMime || !Number.isSafeInteger(info.size) || info.size < 1) {
    throw new Error("Tinify returned invalid output metadata");
  }
  return { imageId: match[1], size: info.size };
}
const source = $("Set output folder and select images").item.json;
const response = $input.item.json;
if (response.statusCode !== 201) throw new Error("Tinify did not create an optimised image");
const url = response.headers.location;
const { size } = checkShrink({ url, info: response.body.output, outputMime: source.outputMime });
return { json: { url, size } };

function checkBytes({ bytes, mime, outputMime, expectedSize }) {
  const at = (offset, length) => Array.from(bytes.subarray(offset, offset + length));
  const ascii = (offset, length) => String.fromCharCode(...at(offset, length));
  const signature = (expected) => expected.every((value, index) => bytes[index] === value);
  const headers = {
    "image/png": () => signature([137, 80, 78, 71, 13, 10, 26, 10]),
    "image/jpeg": () => signature([255, 216, 255]),
    "image/webp": () => ascii(0, 4) === "RIFF" && ascii(8, 4) === "WEBP",
    "image/avif": () => ascii(4, 4) === "ftyp" && ["avif", "avis"].includes(ascii(8, 4)),
    "image/jxl": () =>
      signature([255, 10]) || signature([0, 0, 0, 12, 74, 88, 76, 32, 13, 10, 135, 10]),
  };
  if (
    String(mime ?? "")
      .split(";")[0]
      .toLowerCase() !== outputMime ||
    bytes.length !== expectedSize ||
    !headers[outputMime]?.()
  ) {
    throw new Error("Tinify did not return the complete expected image");
  }
}
